import { motion } from 'framer-motion'
import { Clock, Store } from 'lucide-react'
import { useIsShopOpen, useNextOpeningTime } from '../hooks/useShopConfig'
import { cn } from '@/utils/cn'

interface ShopClosedBannerProps {
  className?: string
}

export function ShopClosedBanner({ className }: ShopClosedBannerProps) {
  const { data: isOpen, isLoading } = useIsShopOpen()
  const { data: nextOpening } = useNextOpeningTime()

  if (isLoading || isOpen) return null

  return (
    <motion.div
      initial={{ opacity: 0, y: -8 }}
      animate={{ opacity: 1, y: 0 }}
      className={cn(
        'rounded-[20px] p-3.5 flex items-center gap-3 relative overflow-hidden border shadow-sm',
        className
      )}
      style={{
        background: 'linear-gradient(135deg, #FFFBEB 0%, #FEF3C7 100%)',
        borderColor: 'rgba(245, 158, 11, 0.35)',
      }}
    >
      <div
        className="w-10 h-10 rounded-[14px] flex items-center justify-center flex-shrink-0"
        style={{
          background: 'rgba(245, 158, 11, 0.15)',
          border: '1px solid rgba(245, 158, 11, 0.30)',
        }}
      >
        <Store className="w-5 h-5 text-amber-700" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <h3 className="font-black text-xs text-amber-950 uppercase tracking-wide">
            ขณะนี้ร้านอยู่นอกเวลาทำการ
          </h3>
          <span className="text-[9px] font-black px-2 py-0.5 rounded-full bg-amber-200/80 text-amber-800 border border-amber-300">
            CLOSED
          </span>
        </div>
        <p className="text-xs font-bold text-amber-900/80 mt-0.5 truncate">
          {nextOpening ? `เปิดรับออเดอร์อีกครั้ง: ${nextOpening}` : 'เปิดรับออเดอร์ในเวลาทำการ'}
        </p>
      </div>
      <Clock className="w-4 h-4 text-amber-600 flex-shrink-0" />
    </motion.div>
  )
}
